type CoolIconProps = SVGProps<SVGSVGElement>

function CoolSvg({ children, ...props }: CoolIconProps) {
  return (
    <svg
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      {...props}
    >
      {children}
    </svg>
  )
}

function CoolPath({ d }: { d: string }) {
  return <path d={d} stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
}

